-- Generated executable query. Run with SQLite against indus_weave.db.
WITH monthly AS (SELECT substr(month_start,1,7) month,department_key,emp_id,SUM(CASE WHEN upper(component_type)='EARNING' THEN amount ELSE 0 END) payroll_cost FROM fact_payroll_line GROUP BY substr(month_start,1,7),department_key,emp_id), dept AS (SELECT month,department_key,SUM(payroll_cost) total_payroll_cost,COUNT(DISTINCT emp_id) employees,SUM(payroll_cost)/NULLIF(COUNT(DISTINCT emp_id),0) cost_per_employee FROM monthly GROUP BY month,department_key) SELECT p.month,d.department_name,ROUND(p.total_payroll_cost,2) total_payroll_cost,p.employees,ROUND(p.cost_per_employee,2) cost_per_employee,ROUND(LAG(p.cost_per_employee) OVER(PARTITION BY p.department_key ORDER BY p.month),2) prior_month_cost_per_employee,ROUND(100.0*(p.cost_per_employee-LAG(p.cost_per_employee) OVER(PARTITION BY p.department_key ORDER BY p.month))/NULLIF(LAG(p.cost_per_employee) OVER(PARTITION BY p.department_key ORDER BY p.month),0),2) mom_change_pct FROM dept p JOIN dim_department d ON d.department_key=p.department_key ORDER BY p.month,d.department_name;
